// EXPECT: 0
/* _Float16 (IEEE binary16) against gcc. float16_golden.inc holds gcc's own results (generated by float16_gen.c) for
   every arithmetic operation, comparison, conversion and increment, on special values (subnormals, infinities, NaNs,
   ties, the extremes) and on random inputs. A result must be bit for bit gcc's, except that a NaN must be a NaN. The
   exit status is the number of failed checks (at most 100). */

struct f16_bin { unsigned short a, b, add, sub, mul, div; unsigned char eq, ne, lt, le, gt, ge; };
struct f16_un { unsigned short a, inc, dec; unsigned char b; unsigned long long d; unsigned f; };
struct f16_dbl { unsigned long long d; unsigned short h; };
struct f16_s64 { long long v; unsigned short h; };
struct f16_u64 { unsigned long long v; unsigned short h; };
struct f16_mix { unsigned short a; unsigned f, r; };
struct f16_int { unsigned short a; long long v; };

#include "float16_golden.inc"

typedef union { unsigned short u; _Float16 h; } f16u;
typedef union { double d; unsigned long long u; } dbu;
typedef union { float f; unsigned u; } fu;

static int fails;
#define FAIL_IF(c) do { if (c) ++fails; } while (0)

static _Float16 hf(unsigned short b) { f16u x; x.u = b; return x.h; }
static unsigned hb(_Float16 h) { f16u x; x.h = h; return x.u; }

/* a result must be gcc's bits, or a NaN where gcc's is a NaN (the payload is not checked) */
static int same16(unsigned got, unsigned want)
{
	if ((want & 0x7c00) == 0x7c00 && (want & 0x3ff))
		return (got & 0x7c00) == 0x7c00 && (got & 0x3ff) != 0;
	return (got & 0xffff) == want;
}
static int same32(unsigned got, unsigned want)
{
	if ((want & 0x7f800000) == 0x7f800000 && (want & 0x7fffff))
		return (got & 0x7f800000) == 0x7f800000 && (got & 0x7fffff) != 0;
	return got == want;
}
static int same64(unsigned long long got, unsigned long long want)
{
	if ((want & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (want & 0xfffffffffffffull))
		return (got & 0x7ff0000000000000ull) == 0x7ff0000000000000ull && (got & 0xfffffffffffffull) != 0;
	return got == want;
}

/* constants folded by the compiler, and values converted at run time */
static const _Float16 k_tenth = 0.1;
static const _Float16 k_big = 65520.0;
static const _Float16 k_int = 2049;
static const _Float16 k_neg = -65504.0;
static const _Float16 k_min = 5.9604644775390625e-8;
static const _Float16 k_tab[] = {1.0, 2.0, 3.0};

struct f16_pair { char c; _Float16 h; };

static _Float16 twice(_Float16 v) { return v + v; }

char f16_size_is_2[sizeof(_Float16) == 2 ? 1 : -1];

int main(void)
{
	unsigned i, n;

	for (i = 0; i < sizeof f16_bins / sizeof f16_bins[0]; ++i) {
		const struct f16_bin *r = &f16_bins[i];
		_Float16 x = hf(r->a), y = hf(r->b);
		FAIL_IF(!same16(hb(x + y), r->add));
		FAIL_IF(!same16(hb(x - y), r->sub));
		FAIL_IF(!same16(hb(x * y), r->mul));
		FAIL_IF(!same16(hb(x / y), r->div));
		FAIL_IF((x == y) != r->eq);
		FAIL_IF((x != y) != r->ne);
		FAIL_IF((x < y) != r->lt);
		FAIL_IF((x <= y) != r->le);
		FAIL_IF((x > y) != r->gt);
		FAIL_IF((x >= y) != r->ge);
	}
	n = sizeof f16_bins / sizeof f16_bins[0];

	for (i = 0; i < sizeof f16_uns / sizeof f16_uns[0]; ++i) {
		const struct f16_un *r = &f16_uns[i];
		_Float16 x = hf(r->a), inc = x, dec = x;
		dbu d;
		fu f;
		inc++;
		dec--;
		FAIL_IF(!same16(hb(inc), r->inc));
		FAIL_IF(!same16(hb(dec), r->dec));
		FAIL_IF((x ? 1 : 0) != r->b);
		d.d = (double)x;
		FAIL_IF(!same64(d.u, r->d));
		f.f = (float)x;
		FAIL_IF(!same32(f.u, r->f));
		FAIL_IF(!same16(hb(-x), r->a ^ 0x8000));
	}

	for (i = 0; i < sizeof f16_dbls / sizeof f16_dbls[0]; ++i) {
		const struct f16_dbl *r = &f16_dbls[i];
		dbu d;
		_Float16 h;
		d.u = r->d;
		h = (_Float16)d.d;
		FAIL_IF(!same16(hb(h), r->h));
	}

	for (i = 0; i < sizeof f16_s64s / sizeof f16_s64s[0]; ++i) {
		const struct f16_s64 *r = &f16_s64s[i];
		_Float16 h = (_Float16)r->v;
		FAIL_IF(!same16(hb(h), r->h));
	}

	for (i = 0; i < sizeof f16_u64s / sizeof f16_u64s[0]; ++i) {
		const struct f16_u64 *r = &f16_u64s[i];
		_Float16 h = (_Float16)r->v;
		FAIL_IF(!same16(hb(h), r->h));
	}

	for (i = 0; i < sizeof f16_mixes / sizeof f16_mixes[0]; ++i) {
		const struct f16_mix *r = &f16_mixes[i];
		fu f, g;
		f.u = r->f;
		g.f = hf(r->a) + f.f;
		FAIL_IF(!same32(g.u, r->r));
	}

	for (i = 0; i < sizeof f16_ints / sizeof f16_ints[0]; ++i) {
		const struct f16_int *r = &f16_ints[i];
		FAIL_IF((long long)hf(r->a) != r->v);
	}

	/* conversions folded by the compiler, from literals */
	for (i = 0; i < sizeof f16_folds / sizeof f16_folds[0]; ++i)
		FAIL_IF(hb(f16_folds[i]) != f16_foldbits[i]);

	/* folded constants and run-time values */
	FAIL_IF(hb(k_tenth) != 0x2e66);
	FAIL_IF(hb(k_big) != 0x7c00);
	FAIL_IF(hb(k_int) != 0x6800);
	FAIL_IF(hb(k_neg) != 0xfbff);
	FAIL_IF(hb(k_min) != 0x0001);
	FAIL_IF(hb(k_tab[2]) != 0x4200);
	{
		_Float16 t = 0.1;
		FAIL_IF(hb(t) != 0x2e66);
		FAIL_IF(hb(twice(hf(0x3c00))) != 0x4000);
		FAIL_IF(hb(twice(hf(0x7bff))) != 0x7c00);
		t = 1.0;
		t += 0.5;
		t *= 2;
		FAIL_IF(hb(t) != 0x4200);
	}
	{
		struct f16_pair q;
		q.c = 1;
		q.h = 1.5;
		FAIL_IF(hb(q.h) != 0x3e00);
	}
	FAIL_IF(sizeof(struct f16_pair) != 4);
	return fails > 100 ? 100 : fails;
}
